let cells=[];
for(let r=0;r<3;r++) for(let c=0;c<3;c++){
  const div=document.createElement("div"); div.className="cell";
  const img=document.createElement("img"); img.className="spr"; div.appendChild(img);
  const f1=document.createElement("div"); f1.className="frostcorner tl";
  const f2=document.createElement("div"); f2.className="frostcorner br";
  div.appendChild(f1); div.appendChild(f2);
  grid.appendChild(div);
  cells.push({el:div,img:img,row:r,col:c});
}
function cellAt(r,c){ return cells.find(x=>x.row===r&&x.col===c); }
function setCellChest(cell,sym,variantIdx){ cell.img.src=SPR[sym.chestVariants[variantIdx]]; cell.sym=sym; cell.variantIdx=variantIdx; }
function randomizeAllCells(){ for(const cell of cells){ const sym=pickSymbol(); setCellChest(cell,sym,pickVariantIndex(sym)); } }
randomizeAllCells();

(function(){ const n=18; for(let i=0;i<n;i++){ const s=document.createElement("span"); const t=i/n; let x,y;
  if(t<0.25){x=t/0.25*100;y=0;} else if(t<0.5){x=100;y=(t-0.25)/0.25*100;} else if(t<0.75){x=100-(t-0.5)/0.25*100;y=100;} else {x=0;y=100-(t-0.75)/0.25*100;}
  s.style.left=x+"%"; s.style.top=y+"%"; s.style.animationDelay=(i*0.09)+"s"; borderLights.appendChild(s); } })();

